using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class HstsHeaderTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;

    public HstsHeaderTests(WebApplicationFactory<Program> factory)
    {
        _factory = factory;
    }

    [Fact]
    public async Task GetRequest_ReturnsHstsHeader()
    {
        var client = _factory.CreateClient();
        var response = await client.GetAsync("/");

        Assert.True(response.Headers.Contains("Strict-Transport-Security"));
        var hstsHeader = response.Headers.GetValues("Strict-Transport-Security").First();
        Assert.Contains("max-age=31536000", hstsHeader);
        Assert.Contains("includeSubDomains", hstsHeader);
    }
}

