// Selenium Test Example (Java)
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.devtools.DevTools;
import org.openqa.selenium.devtools.v120.network.Network;
import org.junit.Test;
import static org.junit.Assert.*;

public class HstsHeaderTest {

    @Test
    public void testHstsHeaderPresent() {
        WebDriver driver = new ChromeDriver();
        DevTools devTools = ((ChromeDriver) driver).getDevTools();
        devTools.createSession();

        List<String> hstsHeaders = new ArrayList<>();
        devTools.send(Network.enable(Optional.empty(), Optional.empty(), Optional.empty()));

        devTools.addListener(Network.responseReceived(), response -> {
            response.getResponse().getHeaders().forEach((key, value) -> {
                if (key.equalsIgnoreCase("Strict-Transport-Security")) {
                    hstsHeaders.add(value.toString());
                }
            });
        });

        driver.get("https://yourdomain.com");

        assertFalse("HSTS header not found", hstsHeaders.isEmpty());
        assertTrue("HSTS max-age incorrect", 
            hstsHeaders.get(0).contains("max-age=31536000"));
        assertTrue("includeSubDomains missing", 
            hstsHeaders.get(0).contains("includeSubDomains"));

        driver.quit();
    }
}
